command:
if (args[0] === "on") {
const target = game.user.targets.first();
if (!target) {
  ui.notifications.warn("Aucune cible sélectionnée !");
  return;
}

// Infos de grille
const gridSize = canvas.grid.size;
const tgtPosition = target.position;

// Coordonnées de la case de base de la cible (arrondies à la grille)
const tgtX = tgtPosition.x;
const tgtY = tgtPosition.y;

// Cases adjacentes (haut, bas, gauche, droite)
const adjacents = [
  { x: tgtX,           y: tgtY - gridSize }, // haut
  { x: tgtX,           y: tgtY + gridSize }, // bas
  { x: tgtX - gridSize, y: tgtY },           // gauche
  { x: tgtX + gridSize, y: tgtY }            // droite
];

// Position du token
const start = token.center;

// Cherche la case adjacente la plus proche
let best = null;
let bestD2 = Infinity;
for (let pos of adjacents) {
  const d2 = (pos.x - start.x) ** 2 + (pos.y - start.y) ** 2;
  if (d2 < bestD2) { bestD2 = d2; best = pos; }
}

// Si pas trouvé
if (!best) {
  ui.notifications.error("Impossible de trouver une case adjacente !");
  return;
}

// Séquence de TP
new Sequence()
  .effect()
    .from(token)
    .fadeIn(50)
    .duration(300)
    .fadeOut(150)
    .filter("Blur")
    .elevation(0)
  .effect()
    .file("jb2a.gust_of_wind.veryfast")
    .atLocation(token)
    .stretchTo(best)
    .elevation(0)
  .wait(100)
  .animation()
    .on(token)
    .teleportTo(best)
    .snapToGrid()
    .waitUntilFinished()
  .effect()
    .file("jb2a.wind_lines.01.01")
    .atLocation(best)
    .scaleToObject()
  .play();
}
